/**
 * efa-llama.js
 * ---------------------------------------------------------------------
 * Interactive version of the "3-factor EFA projection strips" figure
 * (plot_loading_strips() / MODEL_FACTORS['Llama-3.2'] in
 * figure_workspace/tables_and_figures.ipynb), across all three models.
 *
 * The static paper figure is three stacked subplots, one per EFA factor,
 * each showing a random 80-trait sample as a beeswarm strip with the
 * top/bottom 5 traits on *that* factor labeled. Here, only one factor is
 * shown at a time (segmented control above the plot switches between
 * them via Plotly.react), all 235 traits are plotted (not a sub-sample —
 * hover reveals every trait), and the labeled traits are a single fixed
 * set (the top/bottom 5 on Factor 1) that stays the same across all
 * three factor views, so a reader can track how a given trait's
 * projection shifts as they switch factors.
 *
 * A second segmented control below the plot switches which model's EFA
 * is shown. Each model's 3-factor solution is fit independently, so a
 * factor's semantic label (Morality/Competence/Sociability) isn't
 * necessarily in the same slot for every model — the top control's
 * subtitle text is re-synced to the active model's factor names on every
 * switch (see syncFactorLabels()) rather than assumed fixed. Switching
 * models jumps straight to that model's Factor 1 rather than tweening,
 * since the two models' factor spaces aren't the same axes.
 *
 * EFA_DATA (defined just above this IIFE) is generated by
 * figure_workspace/interactive_figures/build_efa_projection_data.py and
 * carries all three models, keyed by model slug — regenerate that JSON
 * and paste it in to refresh this widget.
 */
(function () {
  const el = document.getElementById("efa-llama-canvas");
  if (!el || typeof Plotly === "undefined" || typeof EFA_DATA === "undefined") return;

  const MODEL_ORDER = EFA_DATA.modelOrder;
  let modelSlug = MODEL_ORDER[0];

  function activeModel() {
    return EFA_DATA.models[modelSlug];
  }

  const DICT_ORDER = ["sociability", "morality", "assertiveness", "ability"];
  const DICT_LABEL = {
    sociability: "Sociability",
    morality: "Morality",
    assertiveness: "Assertiveness",
    ability: "Ability",
  };
  const DICT_SYMBOL = {
    sociability: "triangle-down",
    morality: "square",
    assertiveness: "star",
    ability: "diamond",
  };

  function cssVar(name) {
    return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  }

  function isDark() {
    return document.documentElement.getAttribute("data-theme") === "dark";
  }

  // Validated against the dataviz-skill CVD/contrast checks for a 2-slot
  // categorical all-pairs palette (see palette.md slots 2/3, "orange" /
  // "aqua") — the site's own --color-accent/--color-secondary pair fails
  // the chroma-floor check for this use, so this widget uses its own
  // pair instead of the sitewide tokens.
  function dirColor(dir) {
    const dark = isDark();
    if (dir === "low") return dark ? "#d95926" : "#eb6834";
    return dark ? "#199e70" : "#1baf7a";
  }

  const DIR_LABEL = { low: "Negative", high: "Positive" };
  const DIR_ORDER = ["high", "low"];

  // Legend-click filtering state, persisted across factor switches (not
  // reset by buildTraces/render) — a dict bucket or valence is hidden
  // when its legend entry has been clicked off.
  const activeDicts = new Set(DICT_ORDER);
  const activeDirs = new Set(DIR_ORDER);

  // One real trace per (dict, dir) combination, each a single solid
  // color/shape so Plotly's own `visible` toggling can filter cleanly —
  // a real trace is never in the legend itself (see the proxy traces
  // below); its visibility is driven by activeDicts/activeDirs instead,
  // via the plotly_legendclick handler wired up in render().
  function buildTraces(factor) {
    const byKey = {};
    DICT_ORDER.forEach((d) =>
      DIR_ORDER.forEach((dir) => (byKey[`${d}|${dir}`] = { x: [], y: [], text: [] }))
    );

    factor.points.forEach((p) => {
      const bucket = byKey[`${p.dict}|${p.dir}`];
      if (!bucket) return;
      bucket.x.push(p.x);
      bucket.y.push(p.y);
      bucket.text.push(
        `<b>${p.term.replace(/_/g, " ")}</b><br>${DICT_LABEL[p.dict]} (${p.dir})<br>loading: ${p.x.toFixed(3)}`
      );
    });

    const dataTraces = [];
    DICT_ORDER.forEach((d) => {
      DIR_ORDER.forEach((dir) => {
        const bucket = byKey[`${d}|${dir}`];
        dataTraces.push({
          x: bucket.x,
          y: bucket.y,
          customdata: bucket.text,
          hovertemplate: "%{customdata}<extra></extra>",
          mode: "markers",
          type: "scatter",
          name: `${DICT_LABEL[d]} (${DIR_LABEL[dir]})`,
          showlegend: false,
          visible: activeDicts.has(d) && activeDirs.has(dir) ? true : "legendonly",
          _dict: d,
          _dir: dir,
          marker: {
            symbol: DICT_SYMBOL[d],
            size: d === "assertiveness" ? 13 : 10,
            color: dirColor(dir),
            line: { color: cssVar("--color-ink"), width: 0.6 },
            opacity: 0.78,
          },
        });
      });
    });

    // Legend-only proxy traces (no real points) so the legend can show
    // the two encodings separately: valence as colored circles, SCM
    // bucket as ink-colored shapes — instead of one swatch per trace
    // that would otherwise have to pick a single, misleading color.
    // Clicking one filters every real trace with a matching _dir/_dict
    // (see the plotly_legendclick handler in render()).
    const ink = cssVar("--color-ink");
    const colorLegendTraces = DIR_ORDER.map((dir) => ({
      x: [null],
      y: [null],
      mode: "markers",
      type: "scatter",
      name: DIR_LABEL[dir],
      showlegend: true,
      visible: activeDirs.has(dir) ? true : "legendonly",
      hoverinfo: "skip",
      _filterType: "dir",
      _filterValue: dir,
      marker: { symbol: "circle", size: 11, color: dirColor(dir) },
    }));
    const shapeLegendTraces = DICT_ORDER.map((d) => ({
      x: [null],
      y: [null],
      mode: "markers",
      type: "scatter",
      name: DICT_LABEL[d],
      showlegend: true,
      visible: activeDicts.has(d) ? true : "legendonly",
      hoverinfo: "skip",
      _filterType: "dict",
      _filterValue: d,
      marker: { symbol: DICT_SYMBOL[d], size: d === "assertiveness" ? 13 : 10, color: ink },
    }));

    return dataTraces.concat(colorLegendTraces, shapeLegendTraces);
  }

  // Applies activeDicts/activeDirs to the currently-plotted real traces
  // (the 8 leading traces built by buildTraces, in the same dict/dir
  // order) without a full re-render, so filtering feels instant.
  function applyFilterState() {
    const indices = [];
    const visible = [];
    el.data.forEach((trace, i) => {
      if (trace._dict === undefined) return; // a legend proxy, not a data trace
      indices.push(i);
      visible.push(activeDicts.has(trace._dict) && activeDirs.has(trace._dir) ? true : "legendonly");
    });
    if (indices.length) Plotly.restyle(el, { visible }, indices);
  }

  // Row y-positions (absolute, in the same data-y space as the jittered
  // points, which live in roughly [-0.5, 0.5]) that a side's labels are
  // stacked into, evenly spread top-to-bottom — mirrors the notebook's
  // np.linspace(0.65, -0.65, n_labels) placement.
  function rowsFor(n) {
    if (n <= 1) return [0];
    const top = 0.58;
    const bottom = -0.58;
    const step = (top - bottom) / (n - 1);
    return Array.from({ length: n }, (_, i) => top - i * step);
  }

  // Below this container width there isn't room for the ~200px side
  // columns the labels normally sit in (matches the site's 1150px/640px
  // layout breakpoints, where full-bleed figures collapse to the ~672px
  // text column or narrower). Below it, labels sit directly beside their
  // point instead, and identifying every other trait falls to hover.
  const COMPACT_WIDTH = 720;

  function buildLabelAnnotations(factor, compact) {
    const byTerm = {};
    factor.points.forEach((p) => (byTerm[p.term] = p));

    const ink = cssVar("--color-ink");
    const border = cssVar("--color-border-strong");
    const bg = cssVar("--color-bg");
    const annotations = [];

    if (compact) {
      // No room for side columns: label each fixed term right next to
      // its own point, alternating above/below to reduce overlap.
      activeModel().labelTerms.forEach((term, i) => {
        const p = byTerm[term];
        if (!p) return;
        annotations.push({
          x: p.x,
          y: p.y,
          xref: "x",
          yref: "y",
          text: p.term.replace(/_/g, " "),
          showarrow: false,
          yshift: i % 2 === 0 ? 16 : -16,
          font: { family: cssVar("--font-sans"), size: 12, color: ink },
          bgcolor: bg,
          bordercolor: border,
          borderwidth: 1,
          borderpad: 4,
        });
      });
      return annotations;
    }

    const left = [];
    const right = [];
    activeModel().labelTerms.forEach((term) => {
      const p = byTerm[term];
      if (!p) return;
      (p.x < 0 ? left : right).push(p);
    });
    left.sort((a, b) => a.x - b.x); // most negative (strongest) first -> top row
    right.sort((a, b) => b.x - a.x); // most positive (strongest) first -> top row

    const span = factor.xrange[1] - factor.xrange[0];
    const leftX = factor.xrange[0] - 0.06 * span;
    const rightX = factor.xrange[1] + 0.06 * span;

    const leftRows = rowsFor(left.length);
    const rightRows = rowsFor(right.length);

    function makeAnnotation(p, textX, textY, xanchor) {
      return {
        x: p.x,
        y: p.y,
        xref: "x",
        yref: "y",
        text: p.term.replace(/_/g, " "),
        showarrow: true,
        arrowcolor: border,
        arrowwidth: 1,
        arrowhead: 0,
        standoff: 2,
        ax: textX,
        ay: textY,
        axref: "x",
        ayref: "y",
        xanchor: xanchor,
        yanchor: "middle",
        font: { family: cssVar("--font-sans"), size: 14, color: ink },
        bgcolor: bg,
        bordercolor: border,
        borderwidth: 1,
        borderpad: 5,
      };
    }

    left.forEach((p, i) => annotations.push(makeAnnotation(p, leftX, leftRows[i], "right")));
    right.forEach((p, i) => annotations.push(makeAnnotation(p, rightX, rightRows[i], "left")));

    return annotations;
  }

  function buildLayout(factor, compact) {
    const sideMargin = compact ? 28 : 210;
    return {
      margin: { t: 16, r: sideMargin, b: 46, l: sideMargin },
      paper_bgcolor: "transparent",
      plot_bgcolor: "transparent",
      showlegend: true,
      legend: {
        orientation: "h",
        x: 0.5,
        xanchor: "center",
        y: -0.16,
        font: { family: cssVar("--font-sans"), color: cssVar("--color-ink"), size: 12 },
      },
      font: { family: cssVar("--font-sans"), color: cssVar("--color-ink") },
      xaxis: {
        title: { text: "Projection onto factor dimension", font: { size: 13 } },
        range: factor.xrange,
        zeroline: true,
        zerolinecolor: cssVar("--color-border-strong"),
        zerolinewidth: 1.5,
        gridcolor: cssVar("--color-border"),
      },
      yaxis: {
        range: [-0.62, 0.62],
        showticklabels: false,
        zeroline: false,
        showgrid: false,
        fixedrange: true,
      },
      annotations: buildLabelAnnotations(factor, compact),
    };
  }

  let currentId = 0;
  const REAL_TRACE_INDICES = Array.from({ length: DICT_ORDER.length * DIR_ORDER.length }, (_, i) => i);

  function render(factorId, animate) {
    const factor = activeModel().factors[factorId];
    const compact = el.clientWidth > 0 && el.clientWidth < COMPACT_WIDTH;
    const traces = buildTraces(factor);
    const layout = buildLayout(factor, compact);
    const config = { displayModeBar: false, responsive: true };
    if (animate) {
      Plotly.react(el, traces, layout, config);
    } else {
      Plotly.newPlot(el, traces, layout, config);
    }
    currentId = factorId;
  }

  render(0, false);

  function easeInOutQuad(t) {
    return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
  }

  // Bumped whenever a new factor switch starts, so an in-flight animation
  // loop from a previous click can tell it's been superseded and stop
  // (rather than fight a newer one for control of the same traces).
  let animGeneration = 0;

  // Smoothly moves every point from its current (x, y) to its position on
  // `newId`'s factor, and tweens the x-axis range to match — same idea as
  // render(), but interpolated over time instead of swapped instantly.
  // Labels/hover text update immediately (see buildLabelAnnotations),
  // since only the points themselves need to read as "moving".
  function animateFactorChange(newId) {
    if (newId === currentId) return;
    const myGen = ++animGeneration;
    // Set immediately (not when the tween finishes) so currentId always
    // means "the requested factor" — otherwise a second click landing
    // mid-animation back on the factor the first click started from would
    // read as a no-op here, even though the plot is nowhere near it yet.
    currentId = newId;
    const newFactor = activeModel().factors[newId];
    const compact = el.clientWidth > 0 && el.clientWidth < COMPACT_WIDTH;

    // Read live, on-screen state as the animation's start point — if a
    // previous tween was interrupted mid-flight, this is wherever it had
    // gotten to, so the new tween continues smoothly instead of jumping.
    const startX = el.data.slice(0, REAL_TRACE_INDICES.length).map((t) => t.x.slice());
    const startY = el.data.slice(0, REAL_TRACE_INDICES.length).map((t) => t.y.slice());
    const startRange = el.layout.xaxis.range.slice();

    const newTraces = buildTraces(newFactor);
    const endX = newTraces.slice(0, REAL_TRACE_INDICES.length).map((t) => t.x);
    const endY = newTraces.slice(0, REAL_TRACE_INDICES.length).map((t) => t.y);
    const endRange = newFactor.xrange;

    // Labels and hover text jump straight to the new factor's values.
    const newLayout = buildLayout(newFactor, compact);
    Plotly.relayout(el, { annotations: newLayout.annotations });
    Plotly.restyle(
      el,
      { customdata: newTraces.slice(0, REAL_TRACE_INDICES.length).map((t) => t.customdata) },
      REAL_TRACE_INDICES
    );

    const duration = 550;
    const t0 = performance.now();

    function step(now) {
      if (myGen !== animGeneration) return; // a newer click took over

      const t = Math.min(1, (now - t0) / duration);
      const e = easeInOutQuad(t);
      const curX = startX.map((arr, i) => arr.map((v, j) => v + (endX[i][j] - v) * e));
      const curY = startY.map((arr, i) => arr.map((v, j) => v + (endY[i][j] - v) * e));
      const curRange = [
        startRange[0] + (endRange[0] - startRange[0]) * e,
        startRange[1] + (endRange[1] - startRange[1]) * e,
      ];

      Plotly.update(el, { x: curX, y: curY }, { "xaxis.range": curRange }, REAL_TRACE_INDICES);

      if (t < 1) {
        requestAnimationFrame(step);
      }
    }

    requestAnimationFrame(step);
  }

  // Legend-click filtering: clicking a legend entry (a proxy trace, see
  // buildTraces) toggles that dict/dir in the shared filter state, then
  // restyles every real data trace that matches. Returning true lets
  // Plotly still run its own default toggle on the clicked proxy itself,
  // which is what dims/undims that legend swatch.
  el.on("plotly_legendclick", function (evt) {
    const trace = evt.data[evt.curveNumber];
    if (!trace || !trace._filterType) return true;
    const turningOff = trace.visible !== "legendonly";
    const set = trace._filterType === "dir" ? activeDirs : activeDicts;
    if (turningOff) set.delete(trace._filterValue);
    else set.add(trace._filterValue);
    applyFilterState();
    return true;
  });

  const thumb = document.getElementById("efa-llama-thumb");
  const buttons = Array.from(document.querySelectorAll("#efa-llama-control .segmented-btn"));

  function moveThumb(btn) {
    if (!thumb) return;
    thumb.style.width = btn.offsetWidth + "px";
    thumb.style.transform = `translateX(${btn.offsetLeft}px)`;
  }

  buttons.forEach((btn) => {
    btn.addEventListener("click", () => {
      const id = Number(btn.dataset.factor);
      if (id === currentId) return;
      buttons.forEach((b) => {
        b.classList.remove("is-active");
        b.setAttribute("aria-selected", "false");
      });
      btn.classList.add("is-active");
      btn.setAttribute("aria-selected", "true");
      moveThumb(btn);
      animateFactorChange(id);
    });
  });

  const activeBtn = buttons.find((b) => b.classList.contains("is-active")) || buttons[0];
  if (activeBtn) requestAnimationFrame(() => moveThumb(activeBtn));
  syncFactorLabels();

  let resizeTimer = null;
  window.addEventListener("resize", () => {
    const btn = buttons.find((b) => b.classList.contains("is-active"));
    if (btn) moveThumb(btn);
    // Re-render (debounced) so the compact/full layout switch takes effect
    // when a resize crosses COMPACT_WIDTH, not just on next factor click.
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => render(currentId, true), 150);
  });

  // Re-render (colors depend on cssVar) when the site's dark-mode toggle flips.
  const observer = new MutationObserver(() => render(currentId, true));
  observer.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });

  // Each model's EFA factors were fit independently, so a factor's
  // semantic name (Morality/Competence/Sociability) isn't necessarily
  // the same for every model at the same index — resync the top
  // control's subtitle text to the active model's factor names whenever
  // the model changes.
  function syncFactorLabels() {
    const factors = activeModel().factors;
    buttons.forEach((btn) => {
      const id = Number(btn.dataset.factor);
      const sub = btn.querySelector(".segmented-sub");
      const factor = factors[id];
      if (sub && factor) sub.textContent = factor.name;
    });
  }

  // Bottom segmented control: switches which model's EFA is plotted.
  // Legend-based dict/dir filtering carries over across a model switch;
  // the factor view resets to Factor 1 (jump, not a tween — the two
  // models' factor spaces aren't the same axes so interpolating between
  // them wouldn't mean anything) and the top control's subtitles are
  // re-synced to the new model's factor names.
  const modelThumb = document.getElementById("efa-llama-model-thumb");
  const modelButtons = Array.from(document.querySelectorAll("#efa-llama-model-control .segmented-btn"));

  function moveModelThumb(btn) {
    if (!modelThumb) return;
    modelThumb.style.width = btn.offsetWidth + "px";
    modelThumb.style.transform = `translateX(${btn.offsetLeft}px)`;
  }

  modelButtons.forEach((btn) => {
    btn.addEventListener("click", () => {
      const slug = btn.dataset.model;
      if (slug === modelSlug) return;
      modelButtons.forEach((b) => {
        b.classList.remove("is-active");
        b.setAttribute("aria-selected", "false");
      });
      btn.classList.add("is-active");
      btn.setAttribute("aria-selected", "true");
      moveModelThumb(btn);
      modelSlug = slug;
      syncFactorLabels();

      // Also reset the top control to Factor 1, since the previously
      // selected factor index may not carry the same meaning (or exist
      // as the "current" view) in the new model.
      buttons.forEach((b) => {
        b.classList.remove("is-active");
        b.setAttribute("aria-selected", "false");
      });
      const firstBtn = buttons[0];
      if (firstBtn) {
        firstBtn.classList.add("is-active");
        firstBtn.setAttribute("aria-selected", "true");
        moveThumb(firstBtn);
      }
      render(0, true);
    });
  });

  const activeModelBtn = modelButtons.find((b) => b.classList.contains("is-active")) || modelButtons[0];
  if (activeModelBtn) requestAnimationFrame(() => moveModelThumb(activeModelBtn));

  window.addEventListener("resize", () => {
    const btn = modelButtons.find((b) => b.classList.contains("is-active"));
    if (btn) moveModelThumb(btn);
  });
})();
